const dpdpSections: Record<string, LegalSection[]> = {
  en: [
    { heading: '1. Overview', paragraphs: ['India’s Digital Personal Data Protection Act 2023 ("DPDP Act") came into force on 11 August 2023. It is India’s first comprehensive personal data protection law and establishes a framework for processing digital personal data, data principal rights, and obligations of data fiduciaries and processors.', 'FactWise Technologies Private Limited ("FactWise", "we", "us") operates a source-to-pay procurement platform for manufacturing and enterprise companies in India. We are committed to DPDP Act compliance as a Data Fiduciary for data we control and as a Data Processor for data processed on behalf of customers.', 'This statement should be read with our Privacy Policy, Terms of Service, and Cookie Policy.'] },
    { heading: '2. Roles Under the DPDP Act', subsections: [{ heading: '2.1 FactWise as Data Fiduciary', paragraphs: ['FactWise is a Data Fiduciary for employee data, account holders, billing contacts, admin users, website visitors, and data processed for our own business purposes such as marketing, fraud prevention, and platform improvement.'] }, { heading: '2.2 FactWise as Data Processor', paragraphs: ['FactWise is a Data Processor for customer-controlled personal data including supplier records, procurement data entered by customer employees, and any data where the customer determines purpose and means of processing. We process this data only on customer instructions and applicable Data Processing Agreements.'] }, { heading: '2.3 Significant Data Fiduciary Readiness', paragraphs: ['FactWise monitors SDF designation developments and maintains readiness for additional obligations such as Data Protection Officer appointment, Data Protection Impact Assessments, algorithmic audits, and data localisation restrictions if designated.'] }] },
    { heading: '3. Lawful Basis for Processing', paragraphs: ['FactWise relies on lawful bases required by the DPDP Act.'], table: { headers: ['Processing Activity', 'Data Subjects', 'Lawful Basis'], rows: dpdpCommonRows.en } },
    { heading: '3.1 Consent Management and Notice', paragraphs: ['Where consent is the lawful basis, FactWise ensures consent is free, specific, informed, and unambiguous. We maintain consent records including timestamp, purpose, and notice version.', 'Before or at collection, FactWise provides clear notice describing the data collected, the purpose of processing, how data principals can exercise rights, and how to raise a grievance.'] },
    { heading: '4. Data Principal Rights', paragraphs: ['Data principals can contact privacy@factwise.io to exercise rights. FactWise responds within 30 days.'], cards: [{ title: '4.1 Right to Information', description: 'Data principals can know whether their personal data is processed, receive a summary of data held, and know processors and recipients.', helperLabel: 'How to exercise:', helper: 'Email privacy@factwise.io. For supplier data managed by a customer organisation, contact that customer; FactWise will assist in forwarding requests.' }, { title: '4.2 Right to Correction and Erasure', description: 'Data principals can correct inaccurate or incomplete data and request erasure when data is no longer needed for the original purpose.', helperLabel: 'How to exercise:', helper: 'Account holders may update data in Settings. Others can email privacy@factwise.io. If erasure is declined due to legal retention, FactWise will provide written reasons.' }, { title: '4.3 Right to Nominate', description: 'Data principals may nominate another individual to exercise DPDP Act rights on their behalf in death or incapacity.', helperLabel: 'How to exercise:', helper: 'Email privacy@factwise.io with nominee details and a signed declaration.' }, { title: '4.4 Right to Grievance Redressal', description: 'Data principals may raise grievances about FactWise data processing. We acknowledge within 72 hours and resolve substantively within 30 days.', helperLabel: 'How to exercise:', helper: 'Email privacy@factwise.io. If unresolved, data principals may approach the Data Protection Board of India once operational.' }] },
    { heading: '5. Data Fiduciary Obligations', tiles: [{ title: 'Purpose Limitation', description: 'Personal data is processed only for the purposes for which it was collected.' }, { title: 'Data Minimisation', description: 'FactWise processes only data necessary for stated procurement workflows.' }, { title: 'Accuracy', description: 'Users can correct their own data; customer-entered supplier data remains the customer’s responsibility.' }, { title: 'Storage Limitation', description: 'Personal data is retained only as necessary and deleted after retention periods.' }, { title: 'Security Safeguards', description: 'Controls include encryption, TLS, role-based access, penetration testing, and immutable audit logs.' }, { title: 'Accountability', description: 'FactWise maintains records for processing purposes, consent, rights requests, incidents, and processors.' }] },
    { heading: '6. Cross-Border Data Transfers', bullets: ['Default: personal data of Indian data principals is processed and stored in India, using AWS ap-south-1 Mumbai.', 'Sub-processors outside India receive only minimum necessary technical data and must provide equivalent protections under data processing agreements.'], paragraphs: ['FactWise will update this section as cross-border transfer rules are notified under the DPDP Act.'] },
    { heading: '7. Processing of Children’s Data', paragraphs: ['The DPDP Act places strict obligations on processing children’s personal data. FactWise does not knowingly collect or process children’s data, does not target children, designs the platform for enterprise procurement users, and deletes any child data if discovered.'] },
    { heading: '8. Data Processor Obligations', bullets: ['Process customer personal data only on documented instructions', 'Bind FactWise personnel with access to confidentiality obligations', 'Implement appropriate technical and organisational security measures', 'Do not engage sub-processors without customer consent', 'Assist customers with data principal rights requests', 'Delete or return personal data within 90 days after termination', 'Notify customers of security incidents within 72 hours'] },
    { heading: '9. Grievance Redressal', paragraphs: ['FactWise has designated privacy@factwise.io as the data protection contact for grievances under Section 13 of the DPDP Act.'], ordered: ['Submit the grievance by email to privacy@factwise.io', 'Include name, contact details, grievance description, and requested resolution', 'FactWise acknowledges within 72 hours', 'FactWise provides a substantive response within 30 days', 'If unresolved, FactWise escalates internally and reverts within a further 14 days', 'If still unresolved, you may approach the Data Protection Board of India once operational'] },
    { heading: '10. Updates to This Statement', paragraphs: ['This statement will be updated when DPDP rules are notified, the Data Protection Board of India issues guidance, or FactWise practices change. Significant updates will be emailed to account administrators.'] },
  ],
};

dpdpSections.zh = [
  { heading: '1. 概述', paragraphs: ['印度《2023 年数字个人数据保护法》（“DPDP Act”）于 2023 年 8 月 11 日生效，是印度首部综合性个人数据保护法律，建立了数字个人数据处理、数据主体权利以及数据受托方和处理方义务框架。', 'FactWise Technologies Private Limited（“FactWise”“我们”）为印度制造业和企业客户运营寻源到付款采购平台。对于我们控制的数据，我们作为 Data Fiduciary 遵守 DPDP Act；对于代表客户处理的数据，我们作为 Data Processor 遵守 DPDP Act。', '本声明应与我们的隐私政策、服务条款和 Cookie 政策一起阅读。'] },
  { heading: '2. DPDP Act 下的角色', subsections: [{ heading: '2.1 FactWise 作为 Data Fiduciary', paragraphs: ['FactWise 对员工数据、账户持有人、账单联系人、管理员用户、网站访问者以及营销、欺诈防范和平台改进等自身业务目的处理的数据担任 Data Fiduciary。'] }, { heading: '2.2 FactWise 作为 Data Processor', paragraphs: ['对于客户控制的个人数据，包括供应商记录、客户员工输入的采购数据以及由客户决定处理目的和方式的数据，FactWise 担任 Data Processor。我们仅根据客户指示和适用的数据处理协议处理这些数据。'] }, { heading: '2.3 重要数据受托方准备', paragraphs: ['FactWise 持续关注 SDF 指定进展，并为可能的额外义务做好准备，包括任命数据保护官、数据保护影响评估、算法审计和数据本地化限制。'] }] },
  { heading: '3. 处理的合法依据', paragraphs: ['FactWise 依据 DPDP Act 要求的合法基础处理个人数据。'], table: { headers: ['处理活动', '数据主体', '合法依据'], rows: dpdpCommonRows.zh } },
  { heading: '3.1 同意管理和通知', paragraphs: ['当同意是合法依据时，FactWise 确保同意是自由、具体、知情且明确的，并保留时间戳、目的和通知版本等记录。', '在收集前或收集时，FactWise 会以清晰通知说明收集的数据、处理目的、数据主体如何行使权利以及如何提出申诉。'] },
  { heading: '4. 数据主体权利', paragraphs: ['数据主体可联系 privacy@factwise.io 行使权利。FactWise 会在 30 天内回复。'], cards: [{ title: '4.1 知情权', description: '数据主体可了解其个人数据是否被处理、所持数据摘要以及处理方和接收方身份。', helperLabel: '如何行使：', helper: '发送邮件至 privacy@factwise.io。对于客户组织管理的供应商数据，请联系该客户；FactWise 将协助转交请求。' }, { title: '4.2 更正和删除权', description: '数据主体可更正不准确或不完整数据，并在数据不再需要时请求删除。', helperLabel: '如何行使：', helper: '账户持有人可在设置中更新。其他人可发送邮件至 privacy@factwise.io。若因法定保留义务拒绝删除，FactWise 将提供书面理由。' }, { title: '4.3 指定代理权', description: '数据主体可指定他人在其死亡或无行为能力时代表其行使 DPDP Act 权利。', helperLabel: '如何行使：', helper: '将被指定人信息和签署声明发送至 privacy@factwise.io。' }, { title: '4.4 申诉救济权', description: '数据主体可就 FactWise 的数据处理提出正式申诉。我们在 72 小时内确认，并在 30 天内实质解决。', helperLabel: '如何行使：', helper: '发送邮件至 privacy@factwise.io。如未满意解决，可在印度数据保护委员会运作后向其申诉。' }] },
  { heading: '5. Data Fiduciary 义务', tiles: [{ title: '目的限制', description: '个人数据仅按收集时的目的处理。' }, { title: '数据最小化', description: 'FactWise 仅处理既定采购工作流所需的数据。' }, { title: '准确性', description: '用户可更正自身数据；客户输入的供应商数据准确性由客户负责。' }, { title: '存储限制', description: '个人数据仅在必要期间保留，并在保留期后删除。' }, { title: '安全保障', description: '控制措施包括加密、TLS、基于角色的访问、渗透测试和不可变审计日志。' }, { title: '问责', description: 'FactWise 维护处理目的、同意、权利请求、事件和处理方记录。' }] },
  { heading: '6. 跨境数据传输', bullets: ['默认：印度数据主体的个人数据在印度处理和存储，使用 AWS ap-south-1 孟买区域。', '印度以外的子处理方仅接收最低必要技术数据，并须通过数据处理协议提供同等保护。'], paragraphs: ['随着 DPDP Act 下跨境传输规则发布，FactWise 将更新本节。'] },
  { heading: '7. 儿童数据处理', paragraphs: ['DPDP Act 对处理儿童个人数据提出严格义务。FactWise 不会有意收集或处理儿童数据，不面向儿童，平台专为企业采购用户设计，并会在发现儿童数据后删除。'] },
  { heading: '8. Data Processor 义务', bullets: ['仅按客户书面指示处理个人数据', '要求可访问客户数据的 FactWise 人员承担保密义务', '实施适当技术和组织安全措施', '未经客户同意不聘用子处理方', '协助客户处理数据主体权利请求', '客户关系终止后 90 天内删除或返还个人数据', '在 72 小时内通知客户安全事件'] },
  { heading: '9. 申诉救济', paragraphs: ['FactWise 指定 privacy@factwise.io 作为 DPDP Act 第 13 条下的数据保护申诉联系人。'], ordered: ['通过邮件向 privacy@factwise.io 提交申诉', '包含姓名、联系方式、申诉说明和希望的解决方式', 'FactWise 在 72 小时内确认', 'FactWise 在 30 天内提供实质回复', '如未解决，FactWise 内部升级并在额外 14 天内回复', '仍未解决时，可在印度数据保护委员会运作后向其申诉'] },
  { heading: '10. 本声明更新', paragraphs: ['当 DPDP 规则发布、印度数据保护委员会发布指导或 FactWise 实践发生变化时，本声明将更新。重大更新会通过电子邮件通知账户管理员。'] },
];
dpdpSections.es = [
  { heading: '1. Resumen', paragraphs: ['La Digital Personal Data Protection Act 2023 de India ("DPDP Act") entró en vigor el 11 de agosto de 2023. Es la primera ley integral de protección de datos personales de India y define el marco para tratar datos personales digitales, derechos de los titulares y obligaciones de fiduciarios y procesadores.', 'FactWise Technologies Private Limited ("FactWise", "nosotros") opera una plataforma de abastecimiento a pago para empresas industriales y corporativas en India. Cumplimos la DPDP Act como Data Fiduciary para datos que controlamos y como Data Processor para datos tratados por cuenta de clientes.', 'Esta declaración debe leerse junto con nuestra Política de privacidad, Términos de servicio y Política de cookies.'] },
  { heading: '2. Roles bajo la DPDP Act', subsections: [{ heading: '2.1 FactWise como Data Fiduciary', paragraphs: ['FactWise actúa como Data Fiduciary para datos de empleados, titulares de cuenta, contactos de facturación, administradores, visitantes del sitio y datos usados para fines propios como marketing, prevención de fraude y mejora de la plataforma.'] }, { heading: '2.2 FactWise como Data Processor', paragraphs: ['FactWise actúa como Data Processor para datos personales controlados por clientes, incluidos registros de proveedores, datos de compras ingresados por empleados del cliente y datos cuyo propósito y medios de tratamiento determina el cliente. Solo tratamos estos datos siguiendo instrucciones del cliente y acuerdos de procesamiento aplicables.'] }, { heading: '2.3 Preparación para Significant Data Fiduciary', paragraphs: ['FactWise monitorea las designaciones SDF y mantiene preparación para obligaciones adicionales, como nombramiento de Data Protection Officer, evaluaciones de impacto, auditorías algorítmicas y restricciones de localización de datos si aplica.'] }] },
  { heading: '3. Base legal del tratamiento', paragraphs: ['FactWise se apoya en las bases legales exigidas por la DPDP Act.'], table: { headers: ['Actividad de tratamiento', 'Sujetos de datos', 'Base legal'], rows: dpdpCommonRows.es } },
  { heading: '3.1 Gestión del consentimiento y aviso', paragraphs: ['Cuando el consentimiento es la base legal, FactWise garantiza que sea libre, específico, informado e inequívoco, y conserva registros de fecha, finalidad y versión del aviso.', 'Antes o al momento de recopilar datos, FactWise entrega un aviso claro con los datos recogidos, el propósito, cómo ejercer derechos y cómo presentar una reclamación.'] },
  { heading: '4. Derechos del titular de datos', paragraphs: ['Los titulares pueden contactar a privacy@factwise.io para ejercer derechos. FactWise responde en un plazo de 30 días.'], cards: [{ title: '4.1 Derecho a información', description: 'El titular puede saber si sus datos se tratan, recibir un resumen y conocer procesadores y destinatarios.', helperLabel: 'Cómo ejercerlo:', helper: 'Escribe a privacy@factwise.io. Para datos de proveedores gestionados por un cliente, contacta a ese cliente; FactWise ayudará a remitir la solicitud.' }, { title: '4.2 Derecho de corrección y supresión', description: 'El titular puede corregir datos inexactos o incompletos y pedir supresión cuando ya no sean necesarios.', helperLabel: 'Cómo ejercerlo:', helper: 'Los titulares de cuenta pueden actualizar datos en Configuración. Otros pueden escribir a privacy@factwise.io. Si la supresión se rechaza por retención legal, FactWise dará razones por escrito.' }, { title: '4.3 Derecho a nominar', description: 'El titular puede nombrar a otra persona para ejercer derechos DPDP en caso de muerte o incapacidad.', helperLabel: 'Cómo ejercerlo:', helper: 'Escribe a privacy@factwise.io con los datos del nominado y una declaración firmada.' }, { title: '4.4 Derecho de reclamación', description: 'El titular puede presentar reclamaciones sobre el tratamiento de datos de FactWise. Acusamos recibo en 72 horas y resolvemos sustancialmente en 30 días.', helperLabel: 'Cómo ejercerlo:', helper: 'Escribe a privacy@factwise.io. Si no se resuelve, puede acudir al Data Protection Board of India cuando esté operativo.' }] },
  { heading: '5. Obligaciones del Data Fiduciary', tiles: [{ title: 'Limitación de finalidad', description: 'Los datos personales se tratan solo para los fines para los que fueron recopilados.' }, { title: 'Minimización de datos', description: 'FactWise procesa solo los datos necesarios para los flujos de compras declarados.' }, { title: 'Exactitud', description: 'Los usuarios pueden corregir sus datos; los datos de proveedores ingresados por clientes son responsabilidad del cliente.' }, { title: 'Limitación de almacenamiento', description: 'Los datos se conservan solo mientras sea necesario y se eliminan tras el periodo de retención.' }, { title: 'Medidas de seguridad', description: 'Incluyen cifrado, TLS, acceso por roles, pruebas de penetración y registros de auditoría inmutables.' }, { title: 'Responsabilidad', description: 'FactWise mantiene registros de finalidades, consentimientos, solicitudes de derechos, incidentes y procesadores.' }] },
  { heading: '6. Transferencias transfronterizas', bullets: ['Por defecto, los datos de titulares indios se procesan y almacenan en India, usando AWS ap-south-1 Mumbai.', 'Los subprocesadores fuera de India reciben solo datos técnicos mínimos necesarios y deben ofrecer protecciones equivalentes mediante acuerdos de procesamiento.'], paragraphs: ['FactWise actualizará esta sección cuando se notifiquen reglas de transferencia bajo la DPDP Act.'] },
  { heading: '7. Tratamiento de datos de menores', paragraphs: ['La DPDP Act impone obligaciones estrictas sobre datos de menores. FactWise no recopila ni trata conscientemente datos de menores, no dirige la plataforma a menores, la diseña para usuarios empresariales de compras y elimina cualquier dato de menor si se detecta.'] },
  { heading: '8. Obligaciones del Data Processor', bullets: ['Tratar datos personales de clientes solo bajo instrucciones documentadas', 'Sujetar al personal de FactWise con acceso a obligaciones de confidencialidad', 'Aplicar medidas técnicas y organizativas adecuadas', 'No contratar subprocesadores sin consentimiento del cliente', 'Ayudar al cliente con solicitudes de derechos', 'Eliminar o devolver datos dentro de 90 días tras la terminación', 'Notificar incidentes de seguridad al cliente dentro de 72 horas'] },
  { heading: '9. Resolución de reclamaciones', paragraphs: ['FactWise designó privacy@factwise.io como contacto de protección de datos para reclamaciones bajo la Sección 13 de la DPDP Act.'], ordered: ['Enviar la reclamación por correo a privacy@factwise.io', 'Incluir nombre, contacto, descripción y resolución solicitada', 'FactWise acusa recibo en 72 horas', 'FactWise ofrece respuesta sustancial en 30 días', 'Si no se resuelve, FactWise escala internamente y responde en 14 días adicionales', 'Si sigue sin resolverse, puede acudir al Data Protection Board of India cuando esté operativo'] },
  { heading: '10. Actualizaciones de esta declaración', paragraphs: ['Esta declaración se actualizará cuando se notifiquen reglas DPDP, el Data Protection Board of India emita orientación o cambien las prácticas de FactWise. Las actualizaciones importantes se comunicarán por correo a administradores de cuenta.'] },
];
dpdpSections.fr = [
  { heading: '1. Aperçu', paragraphs: ['Le Digital Personal Data Protection Act 2023 de l’Inde ("DPDP Act") est entré en vigueur le 11 août 2023. Il établit un cadre pour le traitement des données personnelles numériques, les droits des personnes concernées et les obligations des data fiduciaries et processors.', 'FactWise Technologies Private Limited ("FactWise", "nous") exploite une plateforme du sourcing au paiement pour les entreprises industrielles et grandes organisations en Inde. Nous respectons le DPDP Act comme Data Fiduciary pour les données que nous contrôlons et comme Data Processor pour les données traitées pour nos clients.', 'Cette déclaration doit être lue avec notre Politique de confidentialité, nos Conditions de service et notre Politique relative aux cookies.'] },
  { heading: '2. Rôles selon le DPDP Act', subsections: [{ heading: '2.1 FactWise comme Data Fiduciary', paragraphs: ['FactWise est Data Fiduciary pour les données des employés, titulaires de compte, contacts de facturation, administrateurs, visiteurs du site et données utilisées pour nos propres finalités, comme marketing, prévention de fraude et amélioration de la plateforme.'] }, { heading: '2.2 FactWise comme Data Processor', paragraphs: ['FactWise est Data Processor pour les données personnelles contrôlées par ses clients : dossiers fournisseurs, données achats saisies par les employés du client et données dont le client détermine finalités et moyens. Nous les traitons uniquement selon les instructions du client et les accords de traitement applicables.'] }, { heading: '2.3 Préparation Significant Data Fiduciary', paragraphs: ['FactWise suit les évolutions de désignation SDF et se prépare aux obligations supplémentaires possibles, notamment DPO, analyses d’impact, audits algorithmiques et restrictions de localisation des données.'] }] },
  { heading: '3. Base licite du traitement', paragraphs: ['FactWise s’appuie sur les bases licites requises par le DPDP Act.'], table: { headers: ['Activité de traitement', 'Personnes concernées', 'Base licite'], rows: dpdpCommonRows.fr } },
  { heading: '3.1 Gestion du consentement et information', paragraphs: ['Lorsque le consentement est la base licite, FactWise veille à ce qu’il soit libre, spécifique, éclairé et non ambigu, et conserve les enregistrements avec horodatage, finalité et version de l’avis.', 'Avant ou au moment de la collecte, FactWise fournit un avis clair indiquant les données collectées, la finalité, les droits et le mode de réclamation.'] },
  { heading: '4. Droits des personnes concernées', paragraphs: ['Les personnes concernées peuvent écrire à privacy@factwise.io pour exercer leurs droits. FactWise répond sous 30 jours.'], cards: [{ title: '4.1 Droit à l’information', description: 'Savoir si les données sont traitées, obtenir un résumé et connaître les processors et destinataires.', helperLabel: 'Comment l’exercer :', helper: 'Écrire à privacy@factwise.io. Pour les données fournisseurs gérées par un client, contactez ce client ; FactWise aidera au transfert.' }, { title: '4.2 Droit de correction et d’effacement', description: 'Corriger les données inexactes ou incomplètes et demander l’effacement lorsque les données ne sont plus nécessaires.', helperLabel: 'Comment l’exercer :', helper: 'Les titulaires de compte peuvent modifier les paramètres. Les autres peuvent écrire à privacy@factwise.io. En cas de refus lié à une obligation de conservation, FactWise fournira les motifs par écrit.' }, { title: '4.3 Droit de nomination', description: 'Nommer une personne pour exercer les droits DPDP en cas de décès ou d’incapacité.', helperLabel: 'Comment l’exercer :', helper: 'Écrire à privacy@factwise.io avec les informations du mandataire et une déclaration signée.' }, { title: '4.4 Droit de recours', description: 'Déposer une réclamation sur le traitement des données. Nous accusons réception sous 72 heures et répondons sous 30 jours.', helperLabel: 'Comment l’exercer :', helper: 'Écrire à privacy@factwise.io. Si non résolu, la personne peut saisir le Data Protection Board of India lorsqu’il sera opérationnel.' }] },
  { heading: '5. Obligations du Data Fiduciary', tiles: [{ title: 'Limitation de finalité', description: 'Les données sont traitées uniquement pour les finalités de collecte.' }, { title: 'Minimisation', description: 'FactWise traite seulement les données nécessaires aux workflows achats.' }, { title: 'Exactitude', description: 'Les utilisateurs peuvent corriger leurs données ; les données fournisseurs saisies par les clients relèvent de leur responsabilité.' }, { title: 'Durée de conservation', description: 'Les données sont conservées uniquement le temps nécessaire puis supprimées.' }, { title: 'Garanties de sécurité', description: 'Chiffrement, TLS, accès par rôles, tests d’intrusion et journaux d’audit immuables.' }, { title: 'Responsabilité', description: 'FactWise conserve les registres de finalités, consentements, demandes, incidents et processors.' }] },
  { heading: '6. Transferts transfrontaliers', bullets: ['Par défaut, les données des personnes situées en Inde sont traitées et stockées en Inde, sur AWS ap-south-1 Mumbai.', 'Les sous-traitants hors Inde reçoivent seulement les données techniques minimales nécessaires et doivent offrir des protections équivalentes.'], paragraphs: ['FactWise mettra cette section à jour lorsque les règles de transfert du DPDP Act seront publiées.'] },
  { heading: '7. Données des enfants', paragraphs: ['Le DPDP Act impose des obligations strictes pour les données d’enfants. FactWise ne collecte ni ne traite sciemment ces données, ne cible pas les enfants, conçoit la plateforme pour les achats d’entreprise et supprime toute donnée d’enfant détectée.'] },
  { heading: '8. Obligations du Data Processor', bullets: ['Traiter les données client uniquement sur instructions documentées', 'Soumettre le personnel FactWise à la confidentialité', 'Mettre en œuvre des mesures techniques et organisationnelles appropriées', 'Ne pas engager de sous-traitants sans consentement client', 'Aider les clients avec les demandes de droits', 'Supprimer ou restituer les données sous 90 jours après résiliation', 'Notifier les incidents de sécurité sous 72 heures'] },
  { heading: '9. Traitement des réclamations', paragraphs: ['FactWise désigne privacy@factwise.io comme contact de protection des données pour les réclamations au titre de la section 13 du DPDP Act.'], ordered: ['Envoyer la réclamation à privacy@factwise.io', 'Inclure nom, coordonnées, description et résolution demandée', 'FactWise accuse réception sous 72 heures', 'FactWise fournit une réponse substantielle sous 30 jours', 'Si non résolu, FactWise escalade en interne et répond sous 14 jours supplémentaires', 'Si toujours non résolu, vous pouvez saisir le Data Protection Board of India lorsqu’il sera opérationnel'] },
  { heading: '10. Mises à jour', paragraphs: ['Cette déclaration sera mise à jour lorsque les règles DPDP seront publiées, que le Data Protection Board of India émettra des orientations ou que les pratiques de FactWise changeront. Les mises à jour importantes seront envoyées par e-mail aux administrateurs de compte.'] },
];
dpdpSections.ko = [
  { heading: '1. 개요', paragraphs: ['인도의 Digital Personal Data Protection Act 2023("DPDP Act")는 2023년 8월 11일 시행되었습니다. 이는 디지털 개인정보 처리, 데이터 주체 권리, Data Fiduciary와 Data Processor의 의무를 정하는 인도 최초의 포괄적 개인정보 보호법입니다.', 'FactWise Technologies Private Limited("FactWise", "당사")는 인도의 제조 및 엔터프라이즈 기업을 위한 소싱부터 결제까지의 조달 플랫폼을 운영합니다. 당사는 통제하는 데이터에 대해서는 Data Fiduciary로, 고객을 대신해 처리하는 데이터에 대해서는 Data Processor로 DPDP Act를 준수합니다.', '본 선언은 개인정보 처리방침, 서비스 약관, 쿠키 정책과 함께 읽어야 합니다.'] },
  { heading: '2. DPDP Act상의 역할', subsections: [{ heading: '2.1 Data Fiduciary로서의 FactWise', paragraphs: ['FactWise는 직원 데이터, 계정 보유자, 청구 연락처, 관리자, 웹사이트 방문자 및 마케팅, 사기 방지, 플랫폼 개선 등 자체 사업 목적 데이터에 대해 Data Fiduciary입니다.'] }, { heading: '2.2 Data Processor로서의 FactWise', paragraphs: ['FactWise는 고객이 통제하는 공급업체 기록, 고객 직원이 입력한 조달 데이터, 고객이 목적과 수단을 결정하는 데이터에 대해 Data Processor입니다. 당사는 고객 지시와 관련 데이터 처리 계약에 따라서만 처리합니다.'] }, { heading: '2.3 Significant Data Fiduciary 준비', paragraphs: ['FactWise는 SDF 지정 동향을 모니터링하고, 지정 시 Data Protection Officer 임명, 영향평가, 알고리즘 감사, 데이터 현지화 제한 등 추가 의무에 대비합니다.'] }] },
  { heading: '3. 처리의 적법 근거', paragraphs: ['FactWise는 DPDP Act가 요구하는 적법 근거에 따라 처리합니다.'], table: { headers: ['처리 활동', '데이터 주체', '적법 근거'], rows: dpdpCommonRows.ko } },
  { heading: '3.1 동의 관리 및 고지', paragraphs: ['동의가 적법 근거인 경우 FactWise는 자유롭고 구체적이며 충분히 고지되고 명확한 동의를 확보하고, 시간, 목적, 고지 버전 기록을 보관합니다.', '수집 전 또는 수집 시 FactWise는 수집 데이터, 처리 목적, 권리 행사 방법, 불만 제기 방법을 명확히 고지합니다.'] },
  { heading: '4. 데이터 주체 권리', paragraphs: ['데이터 주체는 privacy@factwise.io로 권리를 행사할 수 있습니다. FactWise는 30일 이내 응답합니다.'], cards: [{ title: '4.1 정보권', description: '개인정보 처리 여부, 보유 데이터 요약, Processor와 수신자 정보를 알 권리입니다.', helperLabel: '행사 방법:', helper: 'privacy@factwise.io로 이메일을 보내세요. 고객 조직이 관리하는 공급업체 데이터는 해당 고객에게 연락하면 FactWise가 전달을 지원합니다.' }, { title: '4.2 정정 및 삭제권', description: '부정확하거나 불완전한 데이터를 정정하고, 목적상 더 이상 필요하지 않은 데이터 삭제를 요청할 수 있습니다.', helperLabel: '행사 방법:', helper: '계정 보유자는 설정에서 업데이트할 수 있습니다. 그 외에는 privacy@factwise.io로 문의하세요. 법적 보존 의무로 삭제가 거절되면 FactWise가 서면 사유를 제공합니다.' }, { title: '4.3 지정권', description: '사망 또는 무능력 상황에서 DPDP 권리를 행사할 사람을 지정할 수 있습니다.', helperLabel: '행사 방법:', helper: '지정인 정보와 서명된 선언서를 privacy@factwise.io로 보내세요.' }, { title: '4.4 고충 처리권', description: 'FactWise의 데이터 처리에 대해 공식 고충을 제기할 수 있습니다. 72시간 내 접수하고 30일 내 실질적으로 해결합니다.', helperLabel: '행사 방법:', helper: 'privacy@factwise.io로 문의하세요. 미해결 시 Data Protection Board of India가 운영되면 제기할 수 있습니다.' }] },
  { heading: '5. Data Fiduciary 의무', tiles: [{ title: '목적 제한', description: '개인정보는 수집 목적에 한해서만 처리됩니다.' }, { title: '데이터 최소화', description: 'FactWise는 명시된 조달 워크플로에 필요한 데이터만 처리합니다.' }, { title: '정확성', description: '사용자는 자신의 데이터를 수정할 수 있으며 고객 입력 공급업체 데이터의 정확성은 고객 책임입니다.' }, { title: '보관 제한', description: '개인정보는 필요한 기간만 보관되고 보관 기간 후 삭제됩니다.' }, { title: '보안 조치', description: '암호화, TLS, 역할 기반 접근, 침투 테스트, 변경 불가능한 감사 로그를 포함합니다.' }, { title: '책임성', description: 'FactWise는 처리 목적, 동의, 권리 요청, 사고, Processor 기록을 유지합니다.' }] },
  { heading: '6. 국외 이전', bullets: ['기본적으로 인도 데이터 주체의 개인정보는 AWS ap-south-1 Mumbai를 사용해 인도 내에서 처리 및 저장됩니다.', '인도 외 하위 처리자는 최소한의 기술 데이터만 받으며 데이터 처리 계약에 따른 동등한 보호를 제공해야 합니다.'], paragraphs: ['DPDP Act에 따른 국외 이전 규칙이 고지되면 FactWise는 본 섹션을 업데이트합니다.'] },
  { heading: '7. 아동 데이터 처리', paragraphs: ['DPDP Act는 아동 개인정보 처리에 엄격한 의무를 부과합니다. FactWise는 아동 데이터를 고의로 수집하거나 처리하지 않고, 아동을 대상으로 하지 않으며, 기업 조달 사용자를 위해 설계되었고, 발견 시 해당 데이터를 삭제합니다.'] },
  { heading: '8. Data Processor 의무', bullets: ['문서화된 고객 지시에 따라서만 개인정보 처리', '접근 권한이 있는 FactWise 인력에게 비밀유지 의무 부과', '적절한 기술적 및 조직적 보안 조치 이행', '고객 동의 없이 하위 처리자 이용 금지', '고객의 권리 요청 처리 지원', '종료 후 90일 내 개인정보 삭제 또는 반환', '보안 사고를 72시간 내 고객에게 통지'] },
  { heading: '9. 고충 처리', paragraphs: ['FactWise는 DPDP Act 제13조에 따른 고충 처리를 위해 privacy@factwise.io를 데이터 보호 연락처로 지정했습니다.'], ordered: ['privacy@factwise.io로 고충 제출', '이름, 연락처, 고충 설명, 원하는 해결책 포함', 'FactWise는 72시간 내 접수 확인', 'FactWise는 30일 내 실질적 답변 제공', '미해결 시 내부 에스컬레이션 후 추가 14일 내 회신', '계속 미해결 시 Data Protection Board of India가 운영되면 제기 가능'] },
  { heading: '10. 본 선언 업데이트', paragraphs: ['DPDP 규칙 고지, Data Protection Board of India 지침 발행 또는 FactWise 관행 변경 시 본 선언은 업데이트됩니다. 중요한 업데이트는 계정 관리자에게 이메일로 전달됩니다.'] },
];
dpdpSections.pt = [
  { heading: '1. Visão geral', paragraphs: ['A Digital Personal Data Protection Act 2023 da Índia ("DPDP Act") entrou em vigor em 11 de agosto de 2023. É a primeira lei abrangente de proteção de dados pessoais da Índia e estabelece o tratamento de dados digitais, direitos dos titulares e obrigações de fiduciários e processadores.', 'A FactWise Technologies Private Limited ("FactWise", "nós") opera uma plataforma da origem ao pagamento para empresas industriais e corporativas na Índia. Cumprimos a DPDP Act como Data Fiduciary para dados que controlamos e como Data Processor para dados processados em nome de clientes.', 'Esta declaração deve ser lida com nossa Política de Privacidade, Termos de Serviço e Política de Cookies.'] },
  { heading: '2. Papéis sob a DPDP Act', subsections: [{ heading: '2.1 FactWise como Data Fiduciary', paragraphs: ['FactWise é Data Fiduciary para dados de funcionários, titulares de conta, contatos de cobrança, administradores, visitantes do site e dados usados para fins próprios como marketing, prevenção de fraude e melhoria da plataforma.'] }, { heading: '2.2 FactWise como Data Processor', paragraphs: ['FactWise é Data Processor para dados pessoais controlados por clientes, incluindo registros de fornecedores, dados de compras inseridos por funcionários do cliente e dados cujo propósito e meios de tratamento são definidos pelo cliente. Tratamos esses dados apenas conforme instruções do cliente e acordos aplicáveis.'] }, { heading: '2.3 Preparação para Significant Data Fiduciary', paragraphs: ['FactWise acompanha designações SDF e mantém preparação para obrigações adicionais como DPO, avaliações de impacto, auditorias algorítmicas e restrições de localização de dados.'] }] },
  { heading: '3. Base legal do tratamento', paragraphs: ['FactWise usa as bases legais exigidas pela DPDP Act.'], table: { headers: ['Atividade de tratamento', 'Titulares dos dados', 'Base legal'], rows: dpdpCommonRows.pt } },
  { heading: '3.1 Gestão de consentimento e aviso', paragraphs: ['Quando o consentimento é a base legal, FactWise garante que seja livre, específico, informado e inequívoco, mantendo registros de data, finalidade e versão do aviso.', 'Antes ou no momento da coleta, FactWise fornece aviso claro sobre dados coletados, finalidade, exercício de direitos e apresentação de reclamação.'] },
  { heading: '4. Direitos dos titulares', paragraphs: ['Titulares podem contatar privacy@factwise.io para exercer direitos. FactWise responde em até 30 dias.'], cards: [{ title: '4.1 Direito à informação', description: 'Saber se dados pessoais são tratados, receber resumo dos dados e conhecer processadores e destinatários.', helperLabel: 'Como exercer:', helper: 'Envie e-mail a privacy@factwise.io. Para dados de fornecedores geridos por cliente, contate esse cliente; FactWise ajudará a encaminhar.' }, { title: '4.2 Direito de correção e exclusão', description: 'Corrigir dados inexatos ou incompletos e solicitar exclusão quando não forem mais necessários.', helperLabel: 'Como exercer:', helper: 'Titulares de conta podem atualizar em Configurações. Outros podem enviar e-mail a privacy@factwise.io. Se a exclusão for recusada por retenção legal, FactWise dará motivos por escrito.' }, { title: '4.3 Direito de nomear', description: 'Nomear outra pessoa para exercer direitos DPDP em caso de morte ou incapacidade.', helperLabel: 'Como exercer:', helper: 'Envie os dados do nomeado e declaração assinada a privacy@factwise.io.' }, { title: '4.4 Direito de reclamação', description: 'Apresentar reclamações sobre tratamento de dados da FactWise. Confirmamos em 72 horas e resolvemos substancialmente em 30 dias.', helperLabel: 'Como exercer:', helper: 'Envie e-mail a privacy@factwise.io. Se não resolvido, o titular pode recorrer ao Data Protection Board of India quando estiver operacional.' }] },
  { heading: '5. Obrigações do Data Fiduciary', tiles: [{ title: 'Limitação de finalidade', description: 'Dados pessoais são tratados apenas para os fins de coleta.' }, { title: 'Minimização de dados', description: 'FactWise processa somente os dados necessários para fluxos de compras declarados.' }, { title: 'Exatidão', description: 'Usuários podem corrigir seus dados; dados de fornecedores inseridos por clientes são responsabilidade do cliente.' }, { title: 'Limitação de armazenamento', description: 'Dados são retidos apenas pelo tempo necessário e excluídos após o período de retenção.' }, { title: 'Salvaguardas de segurança', description: 'Incluem criptografia, TLS, acesso por função, testes de penetração e logs de auditoria imutáveis.' }, { title: 'Responsabilização', description: 'FactWise mantém registros de finalidades, consentimentos, solicitações, incidentes e processadores.' }] },
  { heading: '6. Transferências internacionais', bullets: ['Por padrão, dados de titulares indianos são processados e armazenados na Índia, usando AWS ap-south-1 Mumbai.', 'Subprocessadores fora da Índia recebem apenas dados técnicos mínimos necessários e devem oferecer proteções equivalentes.'], paragraphs: ['FactWise atualizará esta seção conforme regras de transferência da DPDP Act forem notificadas.'] },
  { heading: '7. Dados de crianças', paragraphs: ['A DPDP Act impõe obrigações rígidas para dados de crianças. FactWise não coleta nem processa conscientemente dados de crianças, não direciona a plataforma a crianças, foi projetada para compras empresariais e exclui dados infantis se identificados.'] },
  { heading: '8. Obrigações do Data Processor', bullets: ['Processar dados do cliente apenas sob instruções documentadas', 'Vincular pessoal da FactWise a obrigações de confidencialidade', 'Implementar medidas técnicas e organizacionais adequadas', 'Não envolver subprocessadores sem consentimento do cliente', 'Auxiliar clientes com solicitações de direitos', 'Excluir ou devolver dados em até 90 dias após término', 'Notificar incidentes de segurança em até 72 horas'] },
  { heading: '9. Reclamações', paragraphs: ['FactWise designou privacy@factwise.io como contato de proteção de dados para reclamações sob a Seção 13 da DPDP Act.'], ordered: ['Enviar reclamação para privacy@factwise.io', 'Incluir nome, contato, descrição e solução solicitada', 'FactWise confirma em 72 horas', 'FactWise responde substancialmente em 30 dias', 'Se não resolvido, FactWise escala internamente e retorna em mais 14 dias', 'Se ainda não resolvido, você pode recorrer ao Data Protection Board of India quando operacional'] },
  { heading: '10. Atualizações desta declaração', paragraphs: ['Esta declaração será atualizada quando regras DPDP forem notificadas, o Data Protection Board of India emitir orientação ou práticas da FactWise mudarem. Atualizações importantes serão enviadas por e-mail aos administradores de conta.'] },
];
dpdpSections.it = [
  { heading: '1. Panoramica', paragraphs: ['Il Digital Personal Data Protection Act 2023 dell’India ("DPDP Act") è entrato in vigore l’11 agosto 2023. È la prima legge organica indiana sulla protezione dei dati personali e definisce trattamento dei dati digitali, diritti degli interessati e obblighi di fiduciari e responsabili.', 'FactWise Technologies Private Limited ("FactWise", "noi") gestisce una piattaforma dal sourcing al pagamento per aziende manifatturiere ed enterprise in India. Rispettiamo il DPDP Act come Data Fiduciary per i dati che controlliamo e come Data Processor per i dati trattati per conto dei clienti.', 'Questa dichiarazione va letta insieme a Informativa privacy, Termini di servizio e Informativa sui cookie.'] },
  { heading: '2. Ruoli secondo il DPDP Act', subsections: [{ heading: '2.1 FactWise come Data Fiduciary', paragraphs: ['FactWise è Data Fiduciary per dati dei dipendenti, titolari di account, contatti di fatturazione, amministratori, visitatori del sito e dati usati per finalità proprie come marketing, prevenzione frodi e miglioramento piattaforma.'] }, { heading: '2.2 FactWise come Data Processor', paragraphs: ['FactWise è Data Processor per dati personali controllati dai clienti, inclusi record fornitori, dati procurement inseriti dai dipendenti del cliente e dati per cui il cliente determina finalità e mezzi. Li trattiamo solo su istruzioni del cliente e accordi applicabili.'] }, { heading: '2.3 Preparazione Significant Data Fiduciary', paragraphs: ['FactWise monitora gli sviluppi SDF e mantiene preparazione per eventuali obblighi aggiuntivi, inclusi DPO, valutazioni d’impatto, audit algoritmici e restrizioni di localizzazione dati.'] }] },
  { heading: '3. Base giuridica del trattamento', paragraphs: ['FactWise si basa sulle basi giuridiche richieste dal DPDP Act.'], table: { headers: ['Attività di trattamento', 'Interessati', 'Base giuridica'], rows: dpdpCommonRows.it } },
  { heading: '3.1 Gestione del consenso e informativa', paragraphs: ['Quando il consenso è la base giuridica, FactWise garantisce che sia libero, specifico, informato e inequivocabile, conservando data, finalità e versione dell’informativa.', 'Prima o al momento della raccolta, FactWise fornisce un avviso chiaro su dati raccolti, finalità, esercizio dei diritti e reclami.'] },
  { heading: '4. Diritti degli interessati', paragraphs: ['Gli interessati possono contattare privacy@factwise.io per esercitare i diritti. FactWise risponde entro 30 giorni.'], cards: [{ title: '4.1 Diritto all’informazione', description: 'Sapere se i dati sono trattati, ricevere un riepilogo e conoscere processor e destinatari.', helperLabel: 'Come esercitarlo:', helper: 'Scrivi a privacy@factwise.io. Per dati fornitori gestiti da un cliente, contatta quel cliente; FactWise aiuterà a inoltrare.' }, { title: '4.2 Diritto di correzione e cancellazione', description: 'Correggere dati inesatti o incompleti e chiedere cancellazione quando non più necessari.', helperLabel: 'Come esercitarlo:', helper: 'I titolari account possono aggiornare in Impostazioni. Altri possono scrivere a privacy@factwise.io. Se la cancellazione è rifiutata per obbligo legale di conservazione, FactWise fornirà motivi scritti.' }, { title: '4.3 Diritto di nomina', description: 'Nominare una persona per esercitare diritti DPDP in caso di morte o incapacità.', helperLabel: 'Come esercitarlo:', helper: 'Scrivi a privacy@factwise.io con dati del nominato e dichiarazione firmata.' }, { title: '4.4 Diritto di reclamo', description: 'Presentare reclami sul trattamento dati FactWise. Confermiamo entro 72 ore e risolviamo sostanzialmente entro 30 giorni.', helperLabel: 'Come esercitarlo:', helper: 'Scrivi a privacy@factwise.io. Se irrisolto, puoi rivolgerti al Data Protection Board of India quando operativo.' }] },
  { heading: '5. Obblighi del Data Fiduciary', tiles: [{ title: 'Limitazione della finalità', description: 'I dati personali sono trattati solo per le finalità di raccolta.' }, { title: 'Minimizzazione dei dati', description: 'FactWise tratta solo i dati necessari ai workflow procurement dichiarati.' }, { title: 'Accuratezza', description: 'Gli utenti possono correggere i propri dati; i dati fornitori inseriti dai clienti sono responsabilità del cliente.' }, { title: 'Limitazione della conservazione', description: 'I dati sono conservati solo per il periodo necessario e poi eliminati.' }, { title: 'Misure di sicurezza', description: 'Includono crittografia, TLS, accesso per ruoli, penetration test e audit log immutabili.' }, { title: 'Responsabilità', description: 'FactWise mantiene registri di finalità, consensi, richieste, incidenti e processor.' }] },
  { heading: '6. Trasferimenti transfrontalieri', bullets: ['Per impostazione predefinita, i dati degli interessati indiani sono trattati e conservati in India, su AWS ap-south-1 Mumbai.', 'I sub-processor fuori dall’India ricevono solo dati tecnici minimi necessari e devono offrire protezioni equivalenti.'], paragraphs: ['FactWise aggiornerà questa sezione quando saranno notificate le regole di trasferimento del DPDP Act.'] },
  { heading: '7. Dati dei minori', paragraphs: ['Il DPDP Act impone obblighi rigorosi per i dati dei minori. FactWise non raccoglie né tratta consapevolmente dati di minori, non li prende di mira, progetta la piattaforma per utenti procurement aziendali ed elimina eventuali dati rilevati.'] },
  { heading: '8. Obblighi del Data Processor', bullets: ['Trattare dati cliente solo su istruzioni documentate', 'Vincolare il personale FactWise alla riservatezza', 'Implementare misure tecniche e organizzative adeguate', 'Non coinvolgere sub-processor senza consenso cliente', 'Assistere i clienti nelle richieste di diritti', 'Eliminare o restituire dati entro 90 giorni dalla cessazione', 'Notificare incidenti di sicurezza entro 72 ore'] },
  { heading: '9. Gestione dei reclami', paragraphs: ['FactWise ha designato privacy@factwise.io come contatto di protezione dati per reclami ai sensi della Sezione 13 del DPDP Act.'], ordered: ['Inviare il reclamo a privacy@factwise.io', 'Includere nome, contatti, descrizione e soluzione richiesta', 'FactWise conferma entro 72 ore', 'FactWise risponde sostanzialmente entro 30 giorni', 'Se non risolto, FactWise escala internamente e risponde entro ulteriori 14 giorni', 'Se ancora irrisolto, puoi rivolgerti al Data Protection Board of India quando operativo'] },
  { heading: '10. Aggiornamenti', paragraphs: ['Questa dichiarazione sarà aggiornata quando saranno notificate regole DPDP, il Data Protection Board of India emetterà linee guida o cambieranno le pratiche FactWise. Gli aggiornamenti significativi saranno inviati agli amministratori account.'] },
];
dpdpSections.ar = [
  { heading: '1. نظرة عامة', paragraphs: ['دخل قانون حماية البيانات الشخصية الرقمية الهندي لعام 2023 ("DPDP Act") حيز التنفيذ في 11 أغسطس 2023. وهو أول قانون شامل في الهند لحماية البيانات الشخصية ويضع إطارا لمعالجة البيانات الرقمية وحقوق أصحاب البيانات والتزامات الأمناء والمعالجين.', 'تشغل FactWise Technologies Private Limited ("FactWise"، "نحن") منصة مشتريات من التوريد إلى الدفع لشركات التصنيع والمؤسسات في الهند. نلتزم بـ DPDP Act بصفتنا Data Fiduciary للبيانات التي نتحكم بها وData Processor للبيانات التي نعالجها نيابة عن العملاء.', 'يجب قراءة هذا البيان مع سياسة الخصوصية وشروط الخدمة وسياسة ملفات تعريف الارتباط.'] },
  { heading: '2. الأدوار بموجب DPDP Act', subsections: [{ heading: '2.1 FactWise بصفتها Data Fiduciary', paragraphs: ['تعد FactWise Data Fiduciary لبيانات الموظفين وأصحاب الحسابات وجهات اتصال الفوترة والمشرفين وزوار الموقع والبيانات المستخدمة لأغراضنا التجارية مثل التسويق ومنع الاحتيال وتحسين المنصة.'] }, { heading: '2.2 FactWise بصفتها Data Processor', paragraphs: ['تعد FactWise Data Processor للبيانات الشخصية التي يتحكم بها العملاء، بما في ذلك سجلات الموردين وبيانات المشتريات التي يدخلها موظفو العميل وأي بيانات يحدد العميل غرض ووسائل معالجتها. نعالج هذه البيانات فقط وفق تعليمات العميل واتفاقيات معالجة البيانات المعمول بها.'] }, { heading: '2.3 الجاهزية كـ Significant Data Fiduciary', paragraphs: ['تراقب FactWise تطورات تعيين SDF وتحافظ على الجاهزية لالتزامات إضافية مثل تعيين Data Protection Officer وتقييمات الأثر وتدقيق الخوارزميات وقيود توطين البيانات إذا تم التعيين.'] }] },
  { heading: '3. الأساس القانوني للمعالجة', paragraphs: ['تعتمد FactWise على الأسس القانونية المطلوبة بموجب DPDP Act.'], table: { headers: ['نشاط المعالجة', 'أصحاب البيانات', 'الأساس القانوني'], rows: dpdpCommonRows.ar } },
  { heading: '3.1 إدارة الموافقة والإشعار', paragraphs: ['عندما تكون الموافقة هي الأساس القانوني، تضمن FactWise أنها حرة ومحددة ومستنيرة وواضحة، وتحتفظ بسجلات تشمل الوقت والغرض وإصدار الإشعار.', 'قبل جمع البيانات أو عنده، تقدم FactWise إشعارا واضحا يصف البيانات المجمعة والغرض من المعالجة وكيفية ممارسة الحقوق وكيفية تقديم الشكوى.'] },
  { heading: '4. حقوق أصحاب البيانات', paragraphs: ['يمكن لأصحاب البيانات التواصل عبر privacy@factwise.io لممارسة حقوقهم. ترد FactWise خلال 30 يوما.'], cards: [{ title: '4.1 الحق في المعلومات', description: 'معرفة ما إذا كانت البيانات الشخصية تعالج والحصول على ملخص ومعرفة المعالجين والمستلمين.', helperLabel: 'كيفية الممارسة:', helper: 'راسل privacy@factwise.io. بالنسبة لبيانات الموردين التي يديرها عميل، تواصل مع ذلك العميل وستساعد FactWise في تمرير الطلب.' }, { title: '4.2 حق التصحيح والمحو', description: 'تصحيح البيانات غير الدقيقة أو غير المكتملة وطلب المحو عندما لا تعود البيانات ضرورية.', helperLabel: 'كيفية الممارسة:', helper: 'يمكن لأصحاب الحساب التحديث من الإعدادات. يمكن للآخرين مراسلة privacy@factwise.io. إذا رفض المحو بسبب التزام احتفاظ قانوني، ستقدم FactWise أسبابا مكتوبة.' }, { title: '4.3 حق التسمية', description: 'يجوز لصاحب البيانات تسمية شخص آخر لممارسة حقوق DPDP نيابة عنه عند الوفاة أو العجز.', helperLabel: 'كيفية الممارسة:', helper: 'راسل privacy@factwise.io مع بيانات الشخص المسمى وإقرار موقع.' }, { title: '4.4 حق التظلم', description: 'يجوز تقديم تظلمات بشأن معالجة FactWise للبيانات. نؤكد الاستلام خلال 72 ساعة ونقدم حلا موضوعيا خلال 30 يوما.', helperLabel: 'كيفية الممارسة:', helper: 'راسل privacy@factwise.io. إذا لم تحل المسألة، يمكن اللجوء إلى Data Protection Board of India عند بدء عمله.' }] },
  { heading: '5. التزامات Data Fiduciary', tiles: [{ title: 'تحديد الغرض', description: 'تعالج البيانات الشخصية فقط للأغراض التي جمعت من أجلها.' }, { title: 'تقليل البيانات', description: 'تعالج FactWise البيانات اللازمة فقط لسير عمل المشتريات المعلن.' }, { title: 'الدقة', description: 'يمكن للمستخدمين تصحيح بياناتهم؛ وتبقى دقة بيانات الموردين التي يدخلها العملاء مسؤولية العميل.' }, { title: 'حدود التخزين', description: 'تحتفظ البيانات فقط للفترة اللازمة وتحذف بعد مدد الاحتفاظ.' }, { title: 'ضمانات الأمان', description: 'تشمل التشفير وTLS والوصول حسب الدور واختبارات الاختراق وسجلات تدقيق غير قابلة للتغيير.' }, { title: 'المساءلة', description: 'تحتفظ FactWise بسجلات الأغراض والموافقات وطلبات الحقوق والحوادث والمعالجين.' }] },
  { heading: '6. نقل البيانات عبر الحدود', bullets: ['افتراضيا، تعالج وتخزن بيانات أصحاب البيانات الهنود داخل الهند باستخدام AWS ap-south-1 Mumbai.', 'يتلقى المعالجون الفرعيون خارج الهند الحد الأدنى اللازم من البيانات التقنية ويجب أن يوفروا حماية مكافئة.'], paragraphs: ['ستحدّث FactWise هذا القسم عند صدور قواعد النقل عبر الحدود بموجب DPDP Act.'] },
  { heading: '7. معالجة بيانات الأطفال', paragraphs: ['يفرض DPDP Act التزامات صارمة على بيانات الأطفال. لا تجمع FactWise أو تعالج بيانات الأطفال عن علم، ولا تستهدف الأطفال، والمنصة مصممة لمستخدمي مشتريات المؤسسات، ويتم حذف أي بيانات طفل إذا اكتشفت.'] },
  { heading: '8. التزامات Data Processor', bullets: ['معالجة بيانات العملاء الشخصية فقط وفق تعليمات موثقة', 'إلزام موظفي FactWise ذوي الوصول بالسرية', 'تنفيذ تدابير أمنية تقنية وتنظيمية مناسبة', 'عدم إشراك معالجين فرعيين دون موافقة العميل', 'مساعدة العملاء في طلبات حقوق أصحاب البيانات', 'حذف أو إعادة البيانات خلال 90 يوما بعد انتهاء العلاقة', 'إبلاغ العملاء بحوادث الأمن خلال 72 ساعة'] },
  { heading: '9. معالجة التظلمات', paragraphs: ['عينت FactWise العنوان privacy@factwise.io كجهة اتصال لحماية البيانات للتظلمات بموجب القسم 13 من DPDP Act.'], ordered: ['إرسال التظلم إلى privacy@factwise.io', 'تضمين الاسم وبيانات الاتصال ووصف التظلم والحل المطلوب', 'تؤكد FactWise الاستلام خلال 72 ساعة', 'تقدم FactWise ردا موضوعيا خلال 30 يوما', 'إذا لم يحل، تصعد FactWise داخليا وترد خلال 14 يوما إضافيا', 'إذا ظل دون حل، يمكنك اللجوء إلى Data Protection Board of India عند بدء عمله'] },
  { heading: '10. تحديثات هذا البيان', paragraphs: ['سيتم تحديث هذا البيان عند صدور قواعد DPDP أو إرشادات Data Protection Board of India أو تغير ممارسات FactWise. ستُرسل التحديثات المهمة بالبريد الإلكتروني إلى مسؤولي الحسابات.'] },
];

dpdpSections.ja = [
  { heading: '1. 概要', paragraphs: ['インドの Digital Personal Data Protection Act 2023（"DPDP Act"）は 2023 年 8 月 11 日に施行されました。これは、デジタル個人データの処理、データ主体の権利、Data Fiduciary と Data Processor の義務を定める包括的な個人データ保護法です。', 'FactWise Technologies Private Limited（"FactWise"、"当社"）は、インドの製造業およびエンタープライズ企業向けにソーシングから支払いまでの調達プラットフォームを運営しています。当社は、自ら管理するデータについては Data Fiduciary として、顧客に代わって処理するデータについては Data Processor として DPDP Act を遵守します。', '本声明は、プライバシーポリシー、利用規約、Cookie ポリシーと併せてお読みください。'] },
  { heading: '2. DPDP Act における役割', subsections: [{ heading: '2.1 Data Fiduciary としての FactWise', paragraphs: ['FactWise は、従業員データ、アカウント保有者、請求連絡先、管理者、Web サイト訪問者、およびマーケティング、不正防止、プラットフォーム改善など当社自身の事業目的で処理するデータについて Data Fiduciary です。'] }, { heading: '2.2 Data Processor としての FactWise', paragraphs: ['FactWise は、顧客が管理する個人データ、たとえばサプライヤーレコード、顧客従業員が入力する調達データ、処理目的と手段を顧客が決定するデータについて Data Processor です。当社は顧客の指示および適用されるデータ処理契約に従ってのみ処理します。'] }, { heading: '2.3 Significant Data Fiduciary への備え', paragraphs: ['FactWise は SDF 指定の動向を監視し、指定された場合に備えて Data Protection Officer の任命、データ保護影響評価、アルゴリズム監査、データローカライゼーション制限などの追加義務に対応できる体制を維持します。'] }] },
  { heading: '3. 処理の法的根拠', paragraphs: ['FactWise は DPDP Act が求める法的根拠に基づいて個人データを処理します。'], table: { headers: ['処理活動', 'データ主体', '法的根拠'], rows: dpdpCommonRows.ja } },
  { heading: '3.1 同意管理と通知', paragraphs: ['同意が法的根拠となる場合、FactWise は同意が自由で、具体的で、十分に説明され、明確であることを確保し、時刻、目的、通知バージョンを記録します。', '収集前または収集時に、FactWise は収集するデータ、処理目的、権利行使方法、苦情申立て方法を明確に通知します。'] },
  { heading: '4. データ主体の権利', paragraphs: ['データ主体は privacy@factwise.io に連絡して権利を行使できます。FactWise は 30 日以内に回答します。'], cards: [{ title: '4.1 情報を知る権利', description: '自分の個人データが処理されているか、保有データの概要、Processor と受領者を知る権利です。', helperLabel: '行使方法:', helper: 'privacy@factwise.io にメールしてください。顧客組織が管理するサプライヤーデータについては、その顧客に連絡してください。FactWise は転送を支援します。' }, { title: '4.2 訂正および消去の権利', description: '不正確または不完全なデータを訂正し、不要になったデータの消去を求める権利です。', helperLabel: '行使方法:', helper: 'アカウント保有者は設定で更新できます。その他の方は privacy@factwise.io にメールしてください。法的保存義務により消去を拒否する場合、FactWise は書面で理由を示します。' }, { title: '4.3 指名する権利', description: '死亡または能力喪失時に DPDP Act 上の権利を代理行使する人を指名できます。', helperLabel: '行使方法:', helper: '指名者情報と署名済み宣言を privacy@factwise.io に送信してください。' }, { title: '4.4 苦情救済の権利', description: 'FactWise のデータ処理に関する正式な苦情を提出できます。当社は 72 時間以内に受領確認し、30 日以内に実質的に解決します。', helperLabel: '行使方法:', helper: 'privacy@factwise.io にメールしてください。未解決の場合、Data Protection Board of India が運用開始後に申立てできます。' }] },
  { heading: '5. Data Fiduciary の義務', tiles: [{ title: '目的制限', description: '個人データは収集目的の範囲でのみ処理されます。' }, { title: 'データ最小化', description: 'FactWise は明示された調達ワークフローに必要なデータのみを処理します。' }, { title: '正確性', description: 'ユーザーは自身のデータを訂正できます。顧客が入力したサプライヤーデータの正確性は顧客の責任です。' }, { title: '保存制限', description: '個人データは必要な期間のみ保存され、保存期間後に削除されます。' }, { title: 'セキュリティ保護措置', description: '暗号化、TLS、ロールベースアクセス、侵入テスト、改ざん不可の監査ログを含みます。' }, { title: '説明責任', description: 'FactWise は処理目的、同意、権利要求、インシデント、Processor の記録を保持します。' }] },
  { heading: '6. 越境データ移転', bullets: ['原則として、インドのデータ主体の個人データは AWS ap-south-1 Mumbai を使用してインド国内で処理および保存されます。', 'インド国外のサブ Processor には必要最小限の技術データのみが移転され、同等の保護を契約で義務付けます。'], paragraphs: ['DPDP Act に基づく越境移転ルールが通知された場合、FactWise は本節を更新します。'] },
  { heading: '7. 子どものデータ処理', paragraphs: ['DPDP Act は子どもの個人データ処理に厳格な義務を課しています。FactWise は子どものデータを意図的に収集または処理せず、子どもを対象とせず、企業調達ユーザー向けに設計されており、子どものデータを発見した場合は削除します。'] },
  { heading: '8. Data Processor の義務', bullets: ['顧客の文書化された指示に従ってのみ個人データを処理する', '顧客データにアクセスする FactWise 人員に守秘義務を課す', '適切な技術的および組織的セキュリティ対策を実施する', '顧客の同意なしにサブ Processor を利用しない', 'データ主体の権利要求について顧客を支援する', '契約終了後 90 日以内に個人データを削除または返却する', 'セキュリティインシデントを 72 時間以内に顧客へ通知する'] },
  { heading: '9. 苦情救済', paragraphs: ['FactWise は、DPDP Act 第 13 条に基づく苦情窓口として privacy@factwise.io を指定しています。'], ordered: ['privacy@factwise.io に苦情をメールで提出する', '氏名、連絡先、苦情内容、希望する解決方法を含める', 'FactWise は 72 時間以内に受領確認する', 'FactWise は 30 日以内に実質的な回答を提供する', '未解決の場合、FactWise は社内でエスカレーションし、さらに 14 日以内に回答する', 'なお未解決の場合、Data Protection Board of India が運用開始後に申立てできます'] },
  { heading: '10. 本声明の更新', paragraphs: ['DPDP ルールが通知された場合、Data Protection Board of India が指針を出した場合、または FactWise の実務が変更された場合、本声明を更新します。重要な更新はアカウント管理者へメールで通知されます。'] },
];

dpdpSections.de = [
  { heading: '1. Überblick', paragraphs: ['Der indische Digital Personal Data Protection Act 2023 ("DPDP Act") trat am 11. August 2023 in Kraft. Er ist Indiens erstes umfassendes Datenschutzgesetz und regelt die Verarbeitung digitaler personenbezogener Daten, Rechte der Data Principals sowie Pflichten von Data Fiduciaries und Data Processors.', 'FactWise Technologies Private Limited ("FactWise", "wir") betreibt eine Source-to-Pay-Beschaffungsplattform für Fertigungs- und Enterprise-Unternehmen in Indien. Wir erfüllen den DPDP Act als Data Fiduciary für von uns kontrollierte Daten und als Data Processor für Daten, die wir im Auftrag unserer Kunden verarbeiten.', 'Diese Erklärung sollte zusammen mit unserer Datenschutzerklärung, unseren Nutzungsbedingungen und unserer Cookie-Richtlinie gelesen werden.'] },
  { heading: '2. Rollen nach dem DPDP Act', subsections: [{ heading: '2.1 FactWise als Data Fiduciary', paragraphs: ['FactWise ist Data Fiduciary für Mitarbeiterdaten, Kontoinhaber, Abrechnungskontakte, Administratoren, Website-Besucher und Daten, die für eigene Geschäftszwecke wie Marketing, Betrugsprävention und Plattformverbesserung verarbeitet werden.'] }, { heading: '2.2 FactWise als Data Processor', paragraphs: ['FactWise ist Data Processor für von Kunden kontrollierte personenbezogene Daten, einschließlich Lieferantendatensätzen, von Kundenmitarbeitern eingegebenen Beschaffungsdaten und Daten, deren Zweck und Mittel der Kunde festlegt. Wir verarbeiten diese Daten nur nach Kundenanweisung und geltenden Datenverarbeitungsvereinbarungen.'] }, { heading: '2.3 Bereitschaft als Significant Data Fiduciary', paragraphs: ['FactWise beobachtet SDF-Entwicklungen und hält sich für zusätzliche Pflichten bereit, darunter Datenschutzbeauftragter, Datenschutz-Folgenabschätzungen, algorithmische Audits und Datenlokalisierungsbeschränkungen.'] }] },
  { heading: '3. Rechtsgrundlage der Verarbeitung', paragraphs: ['FactWise stützt sich auf die nach dem DPDP Act erforderlichen Rechtsgrundlagen.'], table: { headers: ['Verarbeitungstätigkeit', 'Betroffene', 'Rechtsgrundlage'], rows: dpdpCommonRows.de } },
  { heading: '3.1 Einwilligungsmanagement und Hinweis', paragraphs: ['Wenn Einwilligung die Rechtsgrundlage ist, stellt FactWise sicher, dass sie freiwillig, spezifisch, informiert und eindeutig ist, und speichert Zeitstempel, Zweck und Hinweisversion.', 'Vor oder bei der Erhebung stellt FactWise einen klaren Hinweis zu erhobenen Daten, Zweck, Rechten und Beschwerdewegen bereit.'] },
  { heading: '4. Rechte der Data Principals', paragraphs: ['Data Principals können privacy@factwise.io kontaktieren, um Rechte auszuüben. FactWise antwortet innerhalb von 30 Tagen.'], cards: [{ title: '4.1 Recht auf Information', description: 'Betroffene können erfahren, ob ihre Daten verarbeitet werden, eine Zusammenfassung erhalten und Processor sowie Empfänger kennen.', helperLabel: 'Ausübung:', helper: 'E-Mail an privacy@factwise.io. Für Lieferantendaten, die von einem Kunden verwaltet werden, kontaktieren Sie diesen Kunden; FactWise unterstützt die Weiterleitung.' }, { title: '4.2 Recht auf Berichtigung und Löschung', description: 'Betroffene können unrichtige oder unvollständige Daten berichtigen und Löschung verlangen, wenn Daten nicht mehr erforderlich sind.', helperLabel: 'Ausübung:', helper: 'Kontoinhaber können Daten in den Einstellungen aktualisieren. Andere schreiben an privacy@factwise.io. Wird Löschung wegen gesetzlicher Aufbewahrung abgelehnt, nennt FactWise schriftliche Gründe.' }, { title: '4.3 Recht auf Benennung', description: 'Betroffene können eine Person benennen, die bei Tod oder Handlungsunfähigkeit DPDP-Rechte ausübt.', helperLabel: 'Ausübung:', helper: 'E-Mail an privacy@factwise.io mit Angaben zur benannten Person und unterschriebener Erklärung.' }, { title: '4.4 Recht auf Beschwerde', description: 'Betroffene können Beschwerden zur Datenverarbeitung von FactWise einreichen. Wir bestätigen innerhalb von 72 Stunden und lösen substanziell innerhalb von 30 Tagen.', helperLabel: 'Ausübung:', helper: 'E-Mail an privacy@factwise.io. Wenn ungelöst, kann nach Inbetriebnahme das Data Protection Board of India angerufen werden.' }] },
  { heading: '5. Pflichten als Data Fiduciary', tiles: [{ title: 'Zweckbindung', description: 'Personenbezogene Daten werden nur für die Zwecke verarbeitet, für die sie erhoben wurden.' }, { title: 'Datenminimierung', description: 'FactWise verarbeitet nur Daten, die für die angegebenen Beschaffungsworkflows erforderlich sind.' }, { title: 'Richtigkeit', description: 'Nutzer können eigene Daten korrigieren; vom Kunden eingegebene Lieferantendaten liegen in dessen Verantwortung.' }, { title: 'Speicherbegrenzung', description: 'Daten werden nur so lange wie nötig aufbewahrt und nach Ablauf der Frist gelöscht.' }, { title: 'Sicherheitsmaßnahmen', description: 'Dazu gehören Verschlüsselung, TLS, rollenbasierter Zugriff, Penetrationstests und unveränderliche Audit-Logs.' }, { title: 'Rechenschaftspflicht', description: 'FactWise führt Aufzeichnungen zu Zwecken, Einwilligungen, Rechteanfragen, Vorfällen und Processors.' }] },
  { heading: '6. Grenzüberschreitende Übermittlungen', bullets: ['Standardmäßig werden personenbezogene Daten indischer Data Principals in Indien verarbeitet und gespeichert, mit AWS ap-south-1 Mumbai.', 'Sub-Processors außerhalb Indiens erhalten nur die minimal erforderlichen technischen Daten und müssen gleichwertige Schutzmaßnahmen bieten.'], paragraphs: ['FactWise aktualisiert diesen Abschnitt, sobald Übermittlungsregeln nach dem DPDP Act bekanntgegeben werden.'] },
  { heading: '7. Verarbeitung von Kinderdaten', paragraphs: ['Der DPDP Act stellt strenge Anforderungen an Kinderdaten. FactWise erhebt oder verarbeitet wissentlich keine Kinderdaten, richtet die Plattform nicht an Kinder, gestaltet sie für Unternehmensbeschaffung und löscht entdeckte Kinderdaten.'] },
  { heading: '8. Pflichten als Data Processor', bullets: ['Personenbezogene Kundendaten nur nach dokumentierten Anweisungen verarbeiten', 'FactWise-Personal mit Zugriff zur Vertraulichkeit verpflichten', 'Geeignete technische und organisatorische Sicherheitsmaßnahmen umsetzen', 'Keine Sub-Processors ohne Kundeneinwilligung einsetzen', 'Kunden bei Rechteanfragen unterstützen', 'Daten innerhalb von 90 Tagen nach Vertragsende löschen oder zurückgeben', 'Sicherheitsvorfälle innerhalb von 72 Stunden melden'] },
  { heading: '9. Beschwerdeverfahren', paragraphs: ['FactWise hat privacy@factwise.io als Datenschutzkontakt für Beschwerden nach Section 13 des DPDP Act benannt.'], ordered: ['Beschwerde per E-Mail an privacy@factwise.io senden', 'Name, Kontaktdaten, Beschreibung und gewünschte Lösung angeben', 'FactWise bestätigt innerhalb von 72 Stunden', 'FactWise liefert innerhalb von 30 Tagen eine substanzielle Antwort', 'Falls ungelöst, eskaliert FactWise intern und antwortet innerhalb weiterer 14 Tage', 'Falls weiterhin ungelöst, können Sie nach Inbetriebnahme das Data Protection Board of India anrufen'] },
  { heading: '10. Aktualisierungen dieser Erklärung', paragraphs: ['Diese Erklärung wird aktualisiert, wenn DPDP-Regeln bekanntgegeben werden, das Data Protection Board of India Leitlinien herausgibt oder sich FactWise-Praktiken ändern. Wesentliche Aktualisierungen werden per E-Mail an Kontoadministratoren gesendet.'] },
];

